using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
using UnityEngine.SceneManagement;
namespace Snowglow.Editor {
 public static class CloudFadeAuthoring {
  const string Logs="Logs/Forest500CloudFade";
  static void Check(bool ok,string s){if(!ok)throw new InvalidOperationException("Cloud fade: "+s);}
  public static void Apply(CloudWindController w){
   AssetDatabase.ImportAsset("Assets/Snowglow/Shaders/CloudSky.shader",ImportAssetOptions.ForceUpdate|ImportAssetOptions.ForceSynchronousImport);var material=AssetDatabase.LoadAssetAtPath<Material>("Assets/Snowglow/Catalog/Sources/AngularClouds/CloudPalette.mat");Check(material&&material.shader.isSupported&&!ShaderUtil.ShaderHasError(material.shader),"shader failed");material.renderQueue=3000;material.SetOverrideTag("RenderType","Transparent");material.enableInstancing=true;EditorUtility.SetDirty(material);w.fadeSeconds=12;EditorUtility.SetDirty(w);
  }
  public static string Tests(CloudWindController source){
   Directory.CreateDirectory(Logs);foreach(float speed in new[]{3f,8f}){float previous=1;for(float seconds=12;seconds>=0;seconds-=.25f){float a=source.OpacityAt(source.centre+Vector3.forward*(source.radius-speed*seconds),Vector3.forward*speed);Check(a>=0&&a<=1&&a<=previous+.0001f,"non-monotonic fade");previous=a;}Check(previous==0,"boundary not invisible");Check(source.OpacityAt(source.centre-Vector3.forward*(source.radius-2),Vector3.forward*speed)==1,"upwind entry faded");}
   GameObject root=null;try{root=new GameObject("Disposable cloud fade fixture"){hideFlags=HideFlags.HideAndDontSave};var w=root.AddComponent<CloudWindController>();w.centre=source.centre;w.radius=source.radius;w.fadeSeconds=source.fadeSeconds;w.slots=source.slots.Select(s=>{var go=UnityEngine.Object.Instantiate(s.prefab,root.transform);go.hideFlags=HideFlags.HideAndDontSave;return new CloudWindSlot{initialCloud=go.transform,prefab=s.prefab,placementId=s.placementId,baselineScale=s.baselineScale,sourceBounds=s.sourceBounds};}).ToArray();w.Initialize(411);var selected=w.slots.First(s=>s.current);selected.current.position=w.centre+w.Wind.Direction*(w.radius-w.Wind.Speed*6)+Vector3.up*300;var retired=selected.current;float last=1;for(int i=0;i<5;i++){w.Simulate(1,true);Check(selected.current==retired&&selected.opacity<last,"runtime fade did not progress");last=selected.opacity;var block=new MaterialPropertyBlock();selected.currentRenderers[0].GetPropertyBlock(block);Check(Mathf.Abs(block.GetFloat("_CloudOpacity")-selected.opacity)<.0001f,"renderer opacity not applied");}var pos=retired.position;var opacity=selected.opacity;w.Simulate(10,false);Check(retired.position==pos&&selected.opacity==opacity,"pause changed fade");w.Simulate(2,true);Check(!retired,"expired cloud not destroyed");for(int i=0;i<200;i++){w.Simulate(5,true);Check(w.ActiveCount>=10&&w.ActiveCount<=15,"population drift");foreach(var s in w.slots.Where(s=>s.current))Check(!w.NeedsReplacement(s.current.position)&&s.opacity>=0&&s.opacity<=1,"cloud outside lifecycle bounds");}Check(w.RespawnCount>0,"replenishment did not occur");}finally{if(root)UnityEngine.Object.DestroyImmediate(root);}
   bool async=ShaderUtil.allowAsyncCompilation;try{ShaderUtil.allowAsyncCompilation=false;var prefab=source.slots[0].prefab;long full=Capture(prefab,1,"Cloud-opaque.png"),half=Capture(prefab,.5f,"Cloud-half.png"),zero=Capture(prefab,0,"Cloud-invisible.png");Check(full>10000&&half>full*.25&&half<full*.85&&zero==0,"native alpha rendering failed: "+full+" / "+half+" / "+zero);return "12s smooth fade; downwind/upwind and pause checks, actual disposable cloud destruction/replenishment, 1000s bounded-population simulation and native opacity 1/0.5/0 rendering passed (brightness sums "+full+"/"+half+"/"+zero+").";}finally{ShaderUtil.allowAsyncCompilation=async;}
  }
  static long Capture(GameObject prefab,float alpha,string name){var scene=EditorSceneManager.NewPreviewScene();RenderTexture rt=null;Texture2D image=null;var previous=RenderTexture.active;try{var cloud=UnityEngine.Object.Instantiate(prefab);SceneManager.MoveGameObjectToScene(cloud,scene);var renderer=cloud.GetComponentInChildren<Renderer>();var block=new MaterialPropertyBlock();block.SetFloat("_CloudOpacity",alpha);renderer.SetPropertyBlock(block);var bounds=renderer.bounds;var go=new GameObject("Cloud fade probe");SceneManager.MoveGameObjectToScene(go,scene);var camera=go.AddComponent<Camera>();camera.scene=scene;camera.enabled=false;camera.orthographic=true;camera.orthographicSize=Mathf.Max(bounds.extents.x,bounds.extents.y)*1.25f;camera.aspect=1;camera.clearFlags=CameraClearFlags.SolidColor;camera.backgroundColor=Color.black;camera.nearClipPlane=.1f;camera.farClipPlane=bounds.size.magnitude*10+10;camera.transform.SetPositionAndRotation(bounds.center+Vector3.back*(bounds.size.magnitude*2+1),Quaternion.identity);rt=new RenderTexture(320,320,24);camera.targetTexture=rt;camera.Render();RenderTexture.active=rt;image=new Texture2D(320,320,TextureFormat.RGB24,false);image.ReadPixels(new Rect(0,0,320,320),0,0);image.Apply();File.WriteAllBytes(Logs+"/"+name,image.EncodeToPNG());long sum=image.GetPixels32().Sum(c=>(long)c.r+c.g+c.b);camera.targetTexture=null;return sum;}finally{RenderTexture.active=previous;if(rt){rt.Release();UnityEngine.Object.DestroyImmediate(rt);}if(image)UnityEngine.Object.DestroyImmediate(image);EditorSceneManager.ClosePreviewScene(scene);}}
 }
}
